 To force a textfield in Adobe JavaScript (AJAX) to display columns, you can use a combination of HTML table structure and JavaScript to manipulate the data. Here's a simple example:

1. First, create an HTML structure for your table:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Display Columns in Textfield</title>
</head>
<body>
    <table id="myTable">
        <thead>
            <tr>
                <th>Column 1</th>
                <th>Column 2</th>
                <th>Column 3</th>
            </tr>
        </thead>
        <tbody id="dataContainer"></tbody>
    </table>

    <script src="main.js"></script>
</body>
</html>
```

2. Then, in your JavaScript file (main.js), you can populate the table with data:

```javascript
// Sample data
let data = [
    ['Row 1, Col 1', 'Row 1, Col 2', 'Row 1, Col 3'],
    ['Row 2, Col 1', 'Row 2, Col 2', 'Row 2, Col 3'],
    // Add more rows as needed
];

// Function to create table rows
function createTableRow(rowData) {
    const row = document.createElement('tr');
    rowData.forEach((cellData) => {
        const cell = document.createElement('td');
        cell.textContent = cellData;
        row.appendChild(cell);
    });
    return row;
}

// Populate the table with data
const dataContainer = document.getElementById('dataContainer');
data.forEach((row) => {
    const tableRow = createTableRow(row);
    dataContainer.appendChild(tableRow);
});
```

This example creates a simple HTML table with three columns and populates it with sample data using JavaScript. You can modify the data and table structure to fit your specific needs.

